package org.cbhs.bank.testers;

import org.cbhs.bank.model.Account;

/**
 * Run this class to check Account. Students do not edit this file.
 */
public class AccountTester {
    private static int passed = 0;
    private static int failed = 0;

    public static void main(String[] args) {
        testConstructorAndGetters();
        testDeposit();
        testWithdraw();
        printSummary();
    }

    private static void testConstructorAndGetters() {
        Account account = new Account(1001, "Robotics Club", "checking", 250.00);
        check("account number", account.getAccountNumber() == 1001);
        check("owner name", account.getOwnerName().equals("Robotics Club"));
        check("account type", account.getAccountType().equals("checking"));
        check("starting balance", almostEqual(account.getBalance(), 250.00));
        check("no transactions yet", account.getTransactions().size() == 0);
    }

    private static void testDeposit() {
        Account account = new Account(1001, "Robotics Club", "checking", 250.00);
        check("deposit 20 succeeds", account.deposit(20.00));
        check("balance after deposit", almostEqual(account.getBalance(), 270.00));
        check("deposit 0 fails", !account.deposit(0));
        check("deposit negative fails", !account.deposit(-5));
        check("balance unchanged after bad deposit", almostEqual(account.getBalance(), 270.00));
    }

    private static void testWithdraw() {
        Account account = new Account(1001, "Robotics Club", "checking", 250.00);
        check("withdraw 50 succeeds", account.withdraw(50.00));
        check("balance after withdraw", almostEqual(account.getBalance(), 200.00));
        check("withdraw too much fails", !account.withdraw(1000.00));
        check("withdraw negative fails", !account.withdraw(-1));
        check("balance unchanged after bad withdraw", almostEqual(account.getBalance(), 200.00));
    }

    private static void check(String name, boolean ok) {
        if (ok) {
            passed++;
            System.out.println(name + " ... PASS");
        } else {
            failed++;
            System.out.println(name + " ... FAIL");
        }
    }

    private static boolean almostEqual(double a, double b) {
        return Math.abs(a - b) < 0.001;
    }

    private static void printSummary() {
        System.out.println();
        System.out.println("Passed: " + passed + "  Failed: " + failed);
        if (failed == 0) {
            System.out.println("AccountTester: all tests passed.");
        } else {
            System.out.println("AccountTester: some tests failed.");
        }
    }
}
